package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class ModeRelationsTest {
 private SortedMap<Integer,Integer> counts(Question q){String s=q.prompt.substring(q.prompt.indexOf('[')+1,q.prompt.indexOf(']'));SortedMap<Integer,Integer> out=new TreeMap<>();for(String v:s.split(",\\s*"))out.merge(Integer.parseInt(v),1,Integer::sum);return out;}
 @Test public void publicDataDeterminesCountsAndModeWithoutAnswerMetadata(){Generator g=new Generator(new Random(2010));Set<Integer> positions=new HashSet<>();Set<String> prompts=new HashSet<>();for(int i=0;i<600;i++){Question q=g.next("sec_mode",List.of(),i%2==0);var c=counts(q);int max=Collections.max(c.values());int mode=c.entrySet().stream().filter(e->e.getValue()==max).findFirst().orElseThrow().getKey();assertTrue(new Checker().check(q,List.of(),List.of(""+mode)).correct());positions.add(q.correctChoice);prompts.add(q.prompt);verify(q,c); }assertTrue(prompts.size()>100);assertTrue(positions.containsAll(Set.of(0,1,2,3)));}
 @Test public void savedDifferentCountsRestoreOnlyVersionedStudentWork(){Question q=new Question("sec_mode","자료 [0, 3, 3, 3, 3, 2, 0, 2, 0]의 최빈값은?","","99999");q.diagram=new StudyDiagram("bars",new double[]{4,3,2},"3","0","2");verify(q,counts(q));HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("3",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"3");d.stage=1;var restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("3",restored.entries.get(0));}
 private void verify(Question q,SortedMap<Integer,Integer> c){String signature=q.signature();Arrays.fill(q.answers,"99999");q.choiceInputs=new Rational[]{Rational.of(99999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertFalse(p.canTransfer());assertEquals(c.size()+2,p.size());int k=0;for(var e:c.entrySet()){assertEquals("값 "+e.getKey()+"의 등장 횟수 = ",p.step(k).before);assertTrue(p.step(k).accepts(""+e.getValue()));assertFalse(p.step(k).accepts(""+(e.getValue()+1)));k++;}int max=Collections.max(c.values());assertEquals("가장 큰 등장 횟수 = ",p.step(k).before);assertTrue(p.step(k++).accepts(""+max));assertEquals("최빈값 = ",p.step(k).before);int mode=c.entrySet().stream().filter(e->e.getValue()==max).findFirst().orElseThrow().getKey();assertTrue(p.step(k).accepts(""+mode));assertFalse(p.step(k).accepts(""+(mode+1)));}
}
